import math

def calculate_K(a, b, c):
    # K = sqrt(1001) * (1/sqrt(a) + 1/sqrt(b) + 1/sqrt(c))
    return math.sqrt(1001) * (1/math.sqrt(a) + 1/math.sqrt(b) + 1/math.sqrt(c))

# Check all triples where 1 <= a <= b <= c <= 10
solutions = []
count = 0
for a in range(1, 11):
    for b in range(a, 11):
        for c in range(b, 11):
            K = calculate_K(a, b, c)
            # Check if K is close enough to an integer
            if abs(K - round(K)) < 1e-9:
                count += 1
                solutions.append((a, b, c, round(K)))

print(f"Found {count} solutions (up to permutation) for a, b, c <= 10.")
if count > 0:
    print("Solutions found:", solutions)
else:
    print("No integer solutions found for a, b, c <= 10.")

def count_triples():
    count = 0
    triples = []
    for k in [1, 2, 3]:
        # 1/u + 1/v + 1/w = k
        # u <= 3/k
        for u in range(1, int(3/k) + 2):
            if u == 0: continue
            for v in range(1, int(3/k) + 2):
                if v == 0: continue
                # 1/w = k - 1/u - 1/v
                # w = 1 / (k - 1/u - 1/v)
                denom = k - 1/u - 1/v
                if denom > 1e-9:
                    w = 1 / denom
                    if abs(w - round(w)) < 1e-9:
                        w_int = int(round(w))
                        if w_int > 0:
                            triples.append((u, v, w_int))
    return list(set(triples))

print(count_triples())

def count_triples():
    triples = []
    for k in [1, 2, 3]:
        # 1/u + 1/v + 1/w = k
        # u,v,w are positive integers
        # 1/u < k, so u > 1/k. Since u is a positive integer, u >= 1.
        # Also 1/u + 1/v + 1/w = k implies 3/u >= k, so u <= 3/k.
        for u in range(1, int(3/k) + 1):
            for v in range(1, int(3/k) + 1):
                denom = k - 1/u - 1/v
                if denom > 1e-9:
                    w = 1 / denom
                    if abs(w - round(w)) < 1e-9:
                        w_int = int(round(w))
                        if w_int > 0:
                            triples.append((u, v, w_int))
    return list(set(triples))

